"""Independent literal/mutation tests for the pure consumer, not a T1 decoder.

No producer/Host/fixture/oracle imports or subprocess execution. Only the tested
module is imported; source reads in the dependency test are test inspection.
"""

import ast
from contextlib import ExitStack
from dataclasses import FrozenInstanceError, fields, replace
import json
from pathlib import Path
import sys
import unittest
from unittest.mock import patch

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import validator_stdout_consumer as consumer

# Hand-authored input, not generated by a producer or consumer helper.
_LITERAL = b'''{"format_version":1,"result_scope":"structural-evaluation","mode":"host-preliminary","request_id":"0123456789abcdef0123456789abcdef","binding_status":"BOUND","binding":{"evidence_dir":"/witness/run-17","run_id":"run-17","manifest_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","final_binding_sha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","validator_script_sha256":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","schema_register_version":"rc6.5","schema_register_sha256":"dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd"},"structural_status":"PASS","error_count":0,"ceiling_state":"COMPUTED","computed_ceiling":"PASS"}'''
_BEGIN = b"WEAVER_FORGE_VALIDATOR_RESULT_BEGIN v1\n"
_END = b"\nWEAVER_FORGE_VALIDATOR_RESULT_END v1\n"


def _context():
    return consumer.ExpectedContext(
        request_id="0123456789abcdef0123456789abcdef", mode="host-preliminary",
        binding=consumer.ExpectedBinding(
            evidence_dir="/witness/run-17", run_id="run-17",
            manifest_sha256="a" * 64, final_binding_sha256="b" * 64,
            validator_script_sha256="c" * 64, schema_register_version="rc6.5",
            schema_register_sha256="d" * 64))


def _object():
    return json.loads(_LITERAL)


def _frame(payload=_LITERAL, diagnostic=b"ordinary diagnostics\n"):
    return diagnostic + _BEGIN + payload + _END


def _wire(obj):
    return _frame(json.dumps(obj, ensure_ascii=True, separators=(",", ":")).encode("utf-8"))


class StrictConsumerTests(unittest.TestCase):
    def reject(self, raw, code=None, *, expected=None, exit_code=0):
        with self.assertRaises(consumer.ConsumerRejected) as caught:
            consumer.consume_stdout_v1(raw, _context() if expected is None else expected, exit_code)
        self.assertEqual(str(caught.exception), caught.exception.code)
        if code is not None:
            self.assertEqual(caught.exception.code, code)

    def test_01_preliminary_literal_exact_observation(self):
        got = consumer.consume_stdout_v1(_frame(), _context(), 0)
        self.assertEqual((got.format_version, got.result_scope, got.mode, got.request_id,
                          got.binding_status, got.structural_status, got.error_count,
                          got.ceiling_state, got.computed_ceiling),
                         (1, "structural-evaluation", "host-preliminary",
                          "0123456789abcdef0123456789abcdef", "BOUND", "PASS", 0,
                          "COMPUTED", "PASS"))
        self.assertEqual(got.binding, _context().binding)
        self.assertIsNot(got.binding, _context().binding)

    def test_02_final_distinct_context(self):
        obj = _object()
        obj["mode"] = "final-submission"
        obj["request_id"] = "e" * 32
        expected = replace(_context(), mode="final-submission", request_id="e" * 32)
        got = consumer.consume_stdout_v1(_wire(obj), expected, 0)
        self.assertEqual((got.mode, got.request_id), ("final-submission", "e" * 32))
        self.reject(_wire(obj), expected=_context())

    def test_03_computed_values_pass_and_failure_are_independent(self):
        for status, count, ec in (("PASS", 0, 0), ("FAIL", 3, 1)):
            for ceiling in ("PASS", "PARTIAL", "FAIL", "INDETERMINATE"):
                with self.subTest(status=status, ceiling=ceiling):
                    obj = _object()
                    obj.update(structural_status=status, error_count=count, computed_ceiling=ceiling)
                    got = consumer.consume_stdout_v1(_wire(obj), _context(), ec)
                    self.assertEqual((got.structural_status, got.error_count, got.computed_ceiling),
                                     (status, count, ceiling))

    def test_04_not_computed_bound_failure(self):
        obj = _object()
        obj.update(structural_status="FAIL", error_count=1, ceiling_state="NOT_COMPUTED", computed_ceiling=None)
        got = consumer.consume_stdout_v1(_wire(obj), _context(), 1)
        self.assertEqual((got.structural_status, got.ceiling_state, got.computed_ceiling),
                         ("FAIL", "NOT_COMPUTED", None))

    def test_05_not_computed_cannot_be_pass_or_have_a_value(self):
        obj = _object()
        obj.update(ceiling_state="NOT_COMPUTED", computed_ceiling=None)
        self.reject(_wire(obj), "computed_ceiling")
        obj.update(structural_status="FAIL", error_count=1, computed_ceiling="INDETERMINATE")
        self.reject(_wire(obj), "computed_ceiling", exit_code=1)

    def test_06_unavailable_and_availability_contradictions(self):
        for name in ("run_id", "manifest_sha256", "final_binding_sha256",
                     "validator_script_sha256", "schema_register_sha256"):
            with self.subTest(name=name):
                obj = _object()
                obj["binding"][name] = None
                self.reject(_wire(obj), "binding_status")
                obj.update(binding_status="UNAVAILABLE", structural_status="FAIL", error_count=1)
                self.reject(_wire(obj), "binding_unavailable", exit_code=1)
        obj = _object()
        obj["binding_status"] = "UNAVAILABLE"
        self.reject(_wire(obj), "binding_status")

    def test_07_each_binding_member_compared(self):
        replacements = {"evidence_dir": "/another/run", "run_id": "another-run",
                        "manifest_sha256": "1" * 64, "final_binding_sha256": "2" * 64,
                        "validator_script_sha256": "3" * 64, "schema_register_sha256": "4" * 64}
        for key, value in replacements.items():
            with self.subTest(key=key):
                obj = _object()
                obj["binding"][key] = value
                self.reject(_wire(obj), "binding_mismatch")
        obj = _object()
        obj["binding"]["schema_register_version"] = "rc6.4"
        self.reject(_wire(obj), "binding_version")

    def test_08_request_format_and_expected_value(self):
        for value in ("", "a" * 31, "a" * 33, "A" * 32, "g" * 32, 1, True, None, []):
            with self.subTest(value=value):
                obj = _object()
                obj["request_id"] = value
                self.reject(_wire(obj), "request_id")
        obj = _object()
        obj["request_id"] = "f" * 32
        self.reject(_wire(obj), "request_mismatch")

    def test_09_modes_no_default_or_normalization(self):
        for value in ("", "HOST-PRELIMINARY", "final", None, True, []):
            obj = _object()
            obj["mode"] = value
            self.reject(_wire(obj), "mode")
        obj = _object()
        obj["mode"] = "final-submission"
        self.reject(_wire(obj), "mode_mismatch")

    def test_10_version_and_scope_exact_types(self):
        for key, values, code in (("format_version", (True, 1.0, "1", 0, 2, None), "format_version"),
                                  ("result_scope", ("contract", "STRUCTURAL-EVALUATION", None, 1, []), "result_scope")):
            for value in values:
                obj = _object()
                obj[key] = value
                self.reject(_wire(obj), code)

    def test_11_every_top_field_required_unknown_rejected(self):
        for key in _object():
            obj = _object()
            del obj[key]
            self.reject(_wire(obj), "result_fields")
        for key in ("unknown", "validator_status", "machine_verdict_ceiling"):
            obj = _object()
            obj[key] = "PASS"
            self.reject(_wire(obj), "result_fields")

    def test_12_binding_exact_fields_and_container_types(self):
        for key in _object()["binding"]:
            obj = _object()
            del obj["binding"][key]
            self.reject(_wire(obj), "binding_fields")
        for value in ([], None, "BOUND", 1):
            obj = _object()
            obj["binding"] = value
            self.reject(_wire(obj), "binding_fields")
        obj = _object()
        obj["binding"]["unknown"] = "x"
        self.reject(_wire(obj), "binding_fields")
        for value in (None, True, [], "bound"):
            obj = _object()
            obj["binding_status"] = value
            self.reject(_wire(obj), "binding_status")

    def test_13_error_count_no_bool_float_string_negative(self):
        for value in (True, False, 0.0, 1.0, "0", -1, None, []):
            obj = _object()
            obj["error_count"] = value
            self.reject(_wire(obj), "error_count")

    def test_14_structural_status_and_count_contradictions(self):
        for value in ("FAIL", "pass", None, True, []):
            obj = _object()
            obj["structural_status"] = value
            self.reject(_wire(obj), "structural_status")
        obj = _object()
        obj["error_count"] = 1
        self.reject(_wire(obj), "structural_status")

    def test_15_process_exit_type_domain_and_consistency(self):
        for value in (True, False, 0.0, "0", None, -15, 2, 124, 130, 143, 3221225794):
            self.reject(_frame(), "process_exit", exit_code=value)
        self.reject(_frame(), "exit_consistency", exit_code=1)
        obj = _object()
        obj.update(structural_status="FAIL", error_count=1)
        self.reject(_wire(obj), "exit_consistency", exit_code=0)

    def test_16_ceiling_state_value_types(self):
        for value in (None, True, 1, [], "computed", "UNKNOWN"):
            obj = _object()
            obj["ceiling_state"] = value
            self.reject(_wire(obj), "ceiling_state")
        for value in (None, True, 1, [], "pass", "READY"):
            obj = _object()
            obj["computed_ceiling"] = value
            self.reject(_wire(obj), "computed_ceiling")

    def test_17_json_syntax_and_root(self):
        for payload in (b"", b"{", _LITERAL+b"{}", _LITERAL[:-1]+b",}", b"//comment", b'"text"', b"[]", b"null", b"1", b"true", b"\xef\xbb\xbf"+_LITERAL):
            self.reject(_frame(payload))

    def test_18_duplicate_keys_same_conflicting_nested_escaped(self):
        for field in (b'"format_version":1,', b'"format_version":2,'):
            self.reject(_frame(b"{"+field+_LITERAL[1:]), "json_duplicate_key")
        for field in (b'"run_id":"run-17",', b'"run_id":"forged",', b'"run_\\u0069d":"run-17",'):
            raw = _LITERAL.replace(b'"binding":{', b'"binding":{'+field)
            self.reject(_frame(raw), "json_duplicate_key")

    def test_19_missing_wrong_markers_order_and_version(self):
        for raw in (b"", b"STRUCTURAL VALIDATION: PASS\n", _LITERAL,
                    _END+_LITERAL+_BEGIN, _frame().replace(b"BEGIN v1", b"BEGIN v2"),
                    _frame().replace(b"END v1", b"END v2"),
                    _frame().replace(b"BEGIN v1", b"BEGIN v1 "),
                    _frame().replace(b"END v1", b"END v1 ")):
            self.reject(raw)

    def test_20_truncation_line_breaks_and_trailing_content(self):
        raw = _frame()
        for cut in (1, 2, 10, len(_END), len(_END)+3):
            self.reject(raw[:-cut])
        for bad in (raw+b"\n", raw+b"garbage\n", raw.replace(b"\n", b"\r"),
                    raw.replace(b'"format_version":1,', b'"format_version":1,\n')):
            self.reject(bad)

    def test_21_duplicate_extra_or_partial_frames(self):
        for raw in (_frame()+_frame(), _BEGIN+_frame(), _END+_frame(),
                    _frame()+_BEGIN, _frame()+_END):
            self.reject(raw)

    def test_22_diagnostics_opaque_but_reserved_injections_rejected(self):
        for prefix in (b"WEAVER_FORGE_VALIDATOR_RESULT_BEGIN v1\n",
                       b"  WEAVER_FORGE_VALIDATOR_RESULT_BEGIN v1\n",
                       b'quoted "WEAVER_FORGE_VALIDATOR_RESULT_END v1"\n',
                       b"WEAVER_FORGE_VALIDATOR_RESULT_BEGIN v9\n"):
            self.reject(_frame(diagnostic=prefix), "frame_ambiguous")
        # Human text is not machine authority, even if contradictory or multilingual.
        for text in (b"", b"STRUCTURAL VALIDATION: FAIL\n", "arbitrary 診断 PASS \u2028 notes\n".encode()):
            got = consumer.consume_stdout_v1(_frame(diagnostic=text), _context(), 0)
            self.assertEqual(got.structural_status, "PASS")

    def test_23_lf_crlf_and_json_string_escaping(self):
        for raw in (_frame(), _frame().replace(b"\n", b"\r\n")):
            before = raw[:]
            self.assertEqual(consumer.consume_stdout_v1(raw, _context(), 0).binding.evidence_dir, "/witness/run-17")
            self.assertEqual(raw, before)
        obj = _object()
        path = '/witness/WEAVER_FORGE_VALIDATOR_RESULT_BEGIN v1/"quoted"-雪'
        obj["binding"]["evidence_dir"] = path
        expected = replace(_context(), binding=replace(_context().binding, evidence_dir=path))
        self.assertEqual(consumer.consume_stdout_v1(_wire(obj), expected, 0).binding.evidence_dir, path)

    def test_24_utf8_input_types_and_hostile_subclasses(self):
        self.reject(_frame(diagnostic=b"\xff\n"), "stdout_encoding")
        for raw in ("text", bytearray(_frame()), memoryview(_frame()), None, 1):
            self.reject(raw, "stdout_type")
        class Hostile(bytes):
            def __len__(self):
                raise AssertionError("subclass executed")
        self.reject(Hostile(_frame()), "stdout_type")

    def test_25_hash_format_each_hash(self):
        for key in ("manifest_sha256", "final_binding_sha256", "validator_script_sha256", "schema_register_sha256"):
            for value in ("", "a" * 63, "a" * 65, "A" * 64, "g" * 64, 0, True, []):
                obj = _object()
                obj["binding"][key] = value
                self.reject(_wire(obj), "binding_hash")

    def test_26_run_id_and_register_format(self):
        for value in ("", "..", "run..x", "../x", "a/b", "a b", "雪", 1, True, []):
            obj = _object()
            obj["binding"]["run_id"] = value
            self.reject(_wire(obj), "binding_run_id")
        for value in (None, True, [], "RC6.5", "rc6.4"):
            obj = _object()
            obj["binding"]["schema_register_version"] = value
            self.reject(_wire(obj), "binding_version")

    def test_27_paths_absolute_without_resolution_or_aliasing(self):
        for value in ("relative", "C:relative", "\\relative", "", None, 1, True,
                      "/x/../y", "/x/./y", "C:\\x\\..\\y", "/x\x00y", "/x\ny", "/x\ud800"):
            obj = _object()
            obj["binding"]["evidence_dir"] = value
            self.reject(_wire(obj), "binding_path")
        for value in ("/not-existing/雪", "C:\\witness\\run-17", "\\\\server\\share\\run"):
            obj = _object()
            obj["binding"]["evidence_dir"] = value
            expected = replace(_context(), binding=replace(_context().binding, evidence_dir=value))
            self.assertEqual(consumer.consume_stdout_v1(_wire(obj), expected, 0).binding.evidence_dir, value)
        self.reject(_frame(), "binding_mismatch", expected=replace(_context(), binding=replace(_context().binding, evidence_dir="/witness//run-17")))

    def test_28_expected_context_itself_must_be_complete_valid(self):
        for value in ({}, None, False, replace(_context(), request_id="bad"),
                      replace(_context(), mode="unknown"), replace(_context(), binding={})):
            with self.assertRaises(consumer.ConsumerRejected) as error:
                consumer.consume_stdout_v1(_frame(), value, 0)
            self.assertEqual(error.exception.code, "expected_context")
        for f in fields(consumer.ExpectedBinding):
            expected = replace(_context(), binding=replace(_context().binding, **{f.name: None}))
            self.reject(_frame(), "expected_context", expected=expected)

    def test_29_stdout_limit_inclusive(self):
        raw = _frame()
        exact = b"x" * (1048576-len(raw)-1) + b"\n" + raw
        self.assertEqual(len(exact), 1048576)
        self.assertEqual(consumer.consume_stdout_v1(exact, _context(), 0).structural_status, "PASS")
        self.reject(b"x"+exact, "stdout_size")

    def test_30_json_line_limit_inclusive(self):
        payload = b" " * (65536-len(_LITERAL)) + _LITERAL
        self.assertEqual(len(payload), 65536)
        self.assertEqual(consumer.consume_stdout_v1(_frame(payload), _context(), 0).structural_status, "PASS")
        self.reject(_frame(b" "+payload), "json_size")

    def test_31_nonfinite_giant_integer_and_deep_json(self):
        for token in (b"NaN", b"Infinity", b"-Infinity"):
            self.reject(_frame(_LITERAL.replace(b'"error_count":0', b'"error_count":'+token)), "json_nonfinite")
        self.reject(_frame(_LITERAL.replace(b'"error_count":0', b'"error_count":'+b"9"*21)), "json_integer_size")
        # C JSON implementations differ in recursion capacity; this non-object
        # must reject either during decoding or exact-root validation.
        self.reject(_frame(b"["*2000+b"0"+b"]"*2000))
        obj = _object()
        obj.update(structural_status="FAIL", error_count=99999999999999999999)
        self.assertEqual(consumer.consume_stdout_v1(_wire(obj), _context(), 1).error_count, 99999999999999999999)

    def test_32_replay_boundary_and_determinism(self):
        raw, expected = _frame(), _context()
        first = consumer.consume_stdout_v1(raw, expected, 0)
        self.assertEqual(first, consumer.consume_stdout_v1(raw, expected, 0))
        self.reject(raw, "request_mismatch", expected=replace(expected, request_id="f"*32))
        self.reject(raw, "mode_mismatch", expected=replace(expected, mode="final-submission"))
        # Same context is indistinguishable replay: no pretend freshness attestation.
        self.assertEqual(first, consumer.consume_stdout_v1(raw, expected, 0))

    def test_33_inputs_and_returned_values_immutable(self):
        raw, expected = _frame(), _context()
        before = repr(expected), raw[:]
        got = consumer.consume_stdout_v1(raw, expected, 0)
        self.assertEqual((repr(expected), raw), before)
        for target, name, value in ((got, "structural_status", "FAIL"), (got.binding, "run_id", "x"), (expected, "mode", "x")):
            with self.assertRaises(FrozenInstanceError):
                setattr(target, name, value)

    def test_34_no_contract_or_host_result_promotion(self):
        got = consumer.consume_stdout_v1(_frame(), _context(), 0)
        self.assertEqual({f.name for f in fields(got)}, {"format_version", "result_scope", "mode", "request_id", "binding_status", "binding", "structural_status", "error_count", "ceiling_state", "computed_ceiling"})
        for name in ("validator_status", "machine_verdict_ceiling", "host_gate_ok", "ready", "success_eligible"):
            self.assertFalse(hasattr(got, name))

    def test_35_guarded_external_calls_and_input_unchanged(self):
        raw, expected = _frame(), _context()
        targets = ("builtins.open", "io.open", "os.open", "os.stat", "os.getenv",
                   "pathlib.Path.resolve", "subprocess.Popen", "time.time", "time.monotonic")
        with ExitStack() as stack:
            for target in targets:
                stack.enter_context(patch(target, side_effect=AssertionError("external call")))
            stack.enter_context(patch("os.environ", {}))
            first = consumer.consume_stdout_v1(raw, expected, 0)
            self.reject(raw+b"bad\n")
            self.assertEqual(first, consumer.consume_stdout_v1(raw, expected, 0))
        self.assertEqual(expected, _context())
        self.assertEqual(raw, _frame())

    def test_36_static_dependency_allowlist(self):
        tree = ast.parse(Path(consumer.__file__).read_text(encoding="utf-8"))
        imports = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                imports.update(alias.name for alias in node.names)
            elif isinstance(node, ast.ImportFrom):
                imports.add(node.module)
                if node.module == "pathlib":
                    self.assertEqual({n.name for n in node.names}, {"PurePosixPath", "PureWindowsPath"})
            elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
                self.assertNotIn(node.func.id, {"open", "exec", "eval", "__import__", "print"})
        self.assertEqual(imports, {"dataclasses", "json", "pathlib", "re"})


if __name__ == "__main__":
    unittest.main()
